    enabled: Boolean(handle?.runId),
  });

  const progress =
    (run?.metadata as { progress?: { percentage?: number } } | undefined)
      ?.progress?.percentage ?? 0;
  const isCompleted = run?.status === "COMPLETED";

  return (
